import{frameworkTool,interactionOnly}from"./framework-tool.js";import{defineTool}from"#public/tools/index.js";const noReply=frameworkTool(defineTool({availableInSubagents:!1,description:`End your turn without sending a reply. Use this when nothing needs to be said, such as when a scheduled check finds nothing to report or an action you already took is the whole answer.`,endsTurn:!0,execute:interactionOnly(()=>`No reply was sent.`),inputSchema:{type:`object`,properties:{reason:{type:`string`,description:`Why no reply is needed. Kept in the session history and traces; never sent.`}},additionalProperties:!1}}));export{noReply};